/* SVG charts only. The clone carries its own computed type and paint, and the source is a
 * data URI rather than an external reference, so the canvas never taints. */
export function exportSvgToPng(svgElement, options = {}) {
  const scale = Number(options.scale) > 0 ? Number(options.scale) : 2;
  const background = options.background || null;
  return new Promise((resolve, reject) => {
    if (!svgElement || typeof svgElement.cloneNode !== "function") {
      reject(new Error("no chart to save as an image"));
      return;
    }
    const box = typeof svgElement.getBoundingClientRect === "function"
      ? svgElement.getBoundingClientRect()
      : { width: 0, height: 0 };
    const viewBox = String(svgElement.getAttribute("viewBox") || "").split(/[\s,]+/).map(Number);
    const width = Math.round(box.width || viewBox[2] || 640);
    const height = Math.round(box.height || viewBox[3] || 360);

    const clone = svgElement.cloneNode(true);
    inlineComputedStyles(svgElement, clone);
    clone.setAttribute("xmlns", "http://www.w3.org/2000/svg");
    clone.setAttribute("xmlns:xlink", "http://www.w3.org/1999/xlink");
    clone.setAttribute("width", String(width));
    clone.setAttribute("height", String(height));
    if (!clone.getAttribute("viewBox")) clone.setAttribute("viewBox", `0 0 ${width} ${height}`);

    const markup = new XMLSerializer().serializeToString(clone);
    const image = new Image();
    image.onload = () => {
      try {
        const canvas = document.createElement("canvas");
        canvas.width = Math.max(1, Math.round(width * scale));
        canvas.height = Math.max(1, Math.round(height * scale));
        const ctx = canvas.getContext("2d");
        if (!ctx) { reject(new Error("this widget cannot produce a PNG")); return; }
        if (background) {
          ctx.fillStyle = background;
          ctx.fillRect(0, 0, canvas.width, canvas.height);
        }
        ctx.drawImage(image, 0, 0, canvas.width, canvas.height);
        exportCanvasToPng(canvas).then(resolve, reject);
      } catch (err) {
        reject(err);
      }
    };
    image.onerror = () => reject(new Error("the chart could not be rasterized"));
    image.src = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(markup)}`;
  });
}

