  svg.setAttribute("class", "xrail__icon");
  for (const [name, value] of Object.entries(ICON_SVG_ATTRS)) svg.setAttribute(name, value);
  for (const [tag, attrs] of ICON_SHAPES[kind]) {
    const shape = doc.createElementNS(SVG_NS, tag);
    for (const [name, value] of Object.entries(attrs)) shape.setAttribute(name, value);
    svg.appendChild(shape);
  }
