  const off = doc.createElement("span");
  off.className = "xrail__btn tool__off";
  off.setAttribute("aria-disabled", "true");
  off.setAttribute("title", PNG_UNAVAILABLE_TITLE);
  off.textContent = "PNG";
  return off;
