/* The shape contract §6 names. Registering and rendering happen here; the click listener
 * stays on the island root (bindExportDelegation), because this rail is thrown away and
 * rebuilt on the next filter change and a listener bound here would go with it. */
/* The statement the controls carry is read off the section they export, not declared here --
 * see boundaryFor in dashboard-view.mjs. A call site opts in by putting `boundary: "..."` on
 * the section its table() returns (or `boundary` on the view for a whole surface); there is
 * deliberately no options.boundary, because a rail told one thing while the package manifest
 * reads another is exactly the drift this seam exists to prevent. The rail is rebuilt on every
 * filter change, so the tooltip re-reads the live section each time. */
function boundaryOf(options) {
  let section = null;
  try {
    section = typeof options.table === "function" ? options.table() : null;
  } catch (err) {
    section = null;
  }
  const view = typeof options.view === "function" ? options.view() : options.view;
  return boundaryFor(section, view);
}

export function mountExportRail(host, options = {}) {
  if (!host || typeof host.appendChild !== "function") return null;
  const registry = options.registry || defaultExportRegistry;
  const id = String(
    options.id || (typeof host.getAttribute === "function" && host.getAttribute("data-widget")) || "",
  );
  registry.register(id, { title: options.title, table: options.table, png: options.png });
  const rail = renderExportRail({
    id,
    title: options.title,
    hasPng: typeof options.png === "function",
    boundary: boundaryOf(options),
    doc: options.doc || host.ownerDocument || undefined,
  });
  host.appendChild(rail);
  return rail;
}

/* ---- registry and delegation --------------------------------------------- */

/* Widgets re-render on every filter change, so a rail's buttons are thrown away and rebuilt
 * constantly. The registry holds the id -> live-accessor mapping instead, and one delegated
 * listener on the island root outlives every re-render. */
export function createExportRegistry() {
  const entries = new Map();
  return {
    register(id, entry) {
      const key = String(id);
      entries.set(key, {
        title: (entry && entry.title) || key,
        table: entry && typeof entry.table === "function" ? entry.table : () => null,
        png: entry && typeof entry.png === "function" ? entry.png : null,
      });
      return key;
    },
    get(id) { return entries.get(String(id)) || null; },
    has(id) { return entries.has(String(id)); },
    ids() { return [...entries.keys()]; },
    clear() { entries.clear(); },
  };
}

/* The registry mountExportRail writes into when a caller does not bring its own. */
export const defaultExportRegistry = createExportRegistry();

export function bindExportDelegation(root, registry = defaultExportRegistry, options = {}) {
  if (!root || !registry || typeof root.addEventListener !== "function") return () => {};
  const announce = typeof options.announce === "function" ? options.announce : () => {};
  const viewOf = typeof options.view === "function" ? options.view : () => null;

  const run = (control) => {
    const kind = control.getAttribute("data-export");
    const id = control.getAttribute("data-widget");
    const entry = registry.get(id);
    if (!entry || !kind) return false;
    const title = entry.title || id;
    const view = viewOf();

    /* D7 + D8 together: read what the widget is showing right now, and refuse it out loud
     * if it could carry a person. Nothing below this point runs on an unchecked table. */
    let table = null;
    try {
      table = entry.table();
      assertAggregateSection(table);
    } catch (err) {
      announce(`${title} was not exported: ${(err && err.message) || AGGREGATE_ONLY_TITLE}.`);
      return true;
    }

    if (kind === "xlsx") {
      try {
        const bytes = buildTableXlsx(table, view);
        const saved = downloadBlob(safeFilename(view, table, "xlsx"), new Blob([bytes], { type: XLSX_MIME }));
        /* Only say it happened if it happened. */
        announce(saved ? `Exported ${title} as Excel.` : `${title} could not be exported as Excel.`);
      } catch (err) {
        announce(`${title} could not be exported as Excel.`);
      }
      return true;
    }

    if (kind === "copy") {
      Promise.resolve()
        .then(() => copyTableToClipboard(table, view))
        .then(
          () => announce(`Copied ${title} as a table.`),
          () => announce(`${title} could not be copied. Select the table and copy it manually.`),
        );
      return true;
    }

    if (kind === "png") {
      if (!entry.png) {
        announce(`${title} has no faithful image export.`);
        return true;
      }
      Promise.resolve()
        .then(() => entry.png())
        .then(
          (blob) => {
            if (!blob) { announce(`${title} could not be saved as an image.`); return; }
            const saved = downloadBlob(safeFilename(view, table, "png"), blob);
            announce(saved ? `Saved ${title} as an image.` : `${title} could not be saved as an image.`);
          },
          () => announce(`${title} could not be saved as an image.`),
        );
      return true;
    }

    if (kind === "png-markup") {
      /* The markup layer's control (#257): the widget's own PNG bytes, handed to the layer's
       * annotate accessor, which draws this page's ink and signal pins over them and stamps
       * the footer. Notes never travel; the layer owns that rule. Without a faithful PNG or a
       * mounted layer there is nothing honest to save, so say so instead of saving something. */
      if (!entry.png) {
        announce(`${title} has no faithful image export.`);
        return true;
      }
      if (typeof options.annotate !== "function") {
        announce(`${title} has no markup layer to draw.`);
        return true;
      }
      Promise.resolve()
        .then(() => entry.png())
        .then((blob) => (blob ? options.annotate({ id, control, table, view, blob }) : null))
        .then(
          (blob) => {
            if (!blob) { announce(`${title} could not be saved as an image with markup.`); return; }
            const filename = safeFilename(view, table, "png").replace(/\.png$/, "-markup.png");
            const saved = downloadBlob(filename, blob);
            announce(saved ? `Saved ${title} as an image with markup.` : `${title} could not be saved as an image with markup.`);
          },
          () => announce(`${title} could not be saved as an image with markup.`),
        );
      return true;
    }

    if (kind === "package") {
      /* buildDashboardPackage() hashes every chunk with crypto.subtle, so the package accessor
       * may return a Promise; a plain object is accepted too. Both paths end in one honest
       * announcement, and a rejected build never claims a file was saved. */
      Promise.resolve()
        .then(() => (typeof options.package === "function" ? options.package() : null))
        .then(
          (pkg) => {
            if (!pkg) { announce(`${title} has no package to save.`); return; }
            const saved = downloadPackage(pkg, view);
            /* Only say it happened if it happened -- the same test the xlsx branch makes.
             * "Saved the <title> package" reads as English only for the handful of titles
             * that take a definite article; every announcement in this rail names the thing
             * first and the artifact second, so this one does too. */
            announce(saved ? `Saved ${title} as a JSON package.` : `${title} could not be saved as a package.`);
          },
          () => announce(`${title} could not be saved as a package.`),
        );
      return true;
    }

    return false;
  };

  const controlFrom = (event, selector) => {
    const target = event.target;
    if (!target || typeof target.closest !== "function") return null;
    const control = target.closest(selector);
    if (!control) return null;
    if (typeof root.contains === "function" && !root.contains(control)) return null;
    if (control.getAttribute("aria-disabled") === "true") return null;
    return control;
  };

  const onClick = (event) => {
    const control = controlFrom(event, "[data-export]");
    if (control && run(control)) event.preventDefault();
  };

  /* Native <button> handles keys on its own; this covers a rail rendered into an existing
   * role="button" element, which the older island markup still does in places. */
  const onKeydown = (event) => {
    if (event.key !== "Enter" && event.key !== " " && event.key !== "Spacebar") return;
    const control = controlFrom(event, '[data-export][role="button"]');
    if (control && run(control)) event.preventDefault();
  };

  root.addEventListener("click", onClick);
  root.addEventListener("keydown", onKeydown);
  return () => {
    root.removeEventListener("click", onClick);
    root.removeEventListener("keydown", onKeydown);
  };
}

/* ---- the package --------------------------------------------------------- */

/* The .json package built by dashboard-prompt.mjs ({ manifest, chunks }) lands as a file
 * beside the rail. Person-level sections never reach it: the builder composes from
 * exportableSections, and this download only serializes what it is handed.
 *
 * Returns what downloadBlob returned -- true when a file was actually handed to the browser,
 * false when there was no document to hand it to. It used to return the Blob, which is always
 * truthy, so the caller's "could it be saved?" test could never be false and a refused
 * download still announced a success. Same shape as the xlsx and png branches now. */
export function downloadPackage(pkg, view) {
  const blob = new Blob([JSON.stringify(pkg, null, 2)], { type: JSON_MIME });
  return downloadBlob(safeFilename(view, { id: "package" }, "json"), blob);
}

/* Convenience for an island wiring a whole surface at once: every exportable section that
 * actually has rows becomes a registered widget. */
export function registerViewSections(registry, viewOf) {
  const view = typeof viewOf === "function" ? viewOf() : viewOf;
  const ids = [];
  for (const section of exportableSections(view)) {
    if (!Array.isArray(section.columns) || !section.columns.length) continue;
    const id = section.id;
    ids.push(
      registry.register(id, {
        title: section.heading || id,
        table: () => {
          const live = typeof viewOf === "function" ? viewOf() : view;
          const found = exportableSections(live).find((candidate) => candidate.id === id);
          return found || null;
        },
      }),
    );
  }
  return ids;
}
